globalThis.URL_ENTRY_SPLIT_TARGET_EXECUTED = true;
import { value } from "../../value.js";
const asset = import.meta.resolve("../../asset.txt");

async function load() {
  if (URL_ENTRY_LOADING === "jsonp" && typeof document === "undefined") {
    const originalImportScripts = globalThis.importScripts;
    globalThis.importScripts = () => { throw new Error("Simulated loading failure"); };
    try {
      await import("../../lazy.js");
      throw new Error("Expected a chunk loading failure");
    } catch (error) {
      if (error.name !== "ChunkLoadError" || error.type !== "error") throw error;
    } finally {
      globalThis.importScripts = originalImportScripts;
    }
  }
  // The failed JSONP load must also be retryable.
  return import("../../lazy.js");
}

load().then(({ lazy }) => {
  const result = { value, lazy, asset: asset.endsWith(".txt") };
  if (typeof document === "undefined") {
    postMessage(result);
  } else {
    globalThis.URL_ENTRY_SPLIT_READY(result);
  }
});
